#!/usr/bin/env bash

dump_db() {
	local model="$1"
	local output="$2"
	JUJU_DEV_FEATURE_FLAGS=developer-mode juju dump-db -m "${model}" --format=yaml >"${output}"
}

# dump_db_checked dumps the model and fails the caller if the dump
# cannot be produced.
dump_db_checked() {
	local model="$1"
	local output="$2"
	if ! dump_db "${model}" "${output}"; then
		echo "    FAIL: could not dump model ${model}"
		rm -f "${output}"
		return 1
	fi
}

# The assert helpers below take a <dump_file> as an argument.
# The dump file is generated by dump_db() above.

# Fails if any remoteApplications relationcount is negative.
assert_no_negative_counts() {
	local dump="$1"
	local neg
	neg=$(cat "${dump}" | yq -r '[.remoteApplications[]?.relationcount] | .[] | select(. != null)' 2>/dev/null |
		awk '$1 < 0')
	if [ -n "${neg}" ]; then
		echo "    FAIL: negative relationcount found: ${neg}"
		return 1
	fi
	echo "$(green "no negative relationcounts")"
}

# Fails if any relationscopes or settings document references a
# relation id that does not exist in the relations collection.
assert_no_orphaned_scope_settings() {
	local dump="$1"
	local rel_ids scope_ids settings_ids orphans

	rel_ids=$(cat "${dump}" | yq -r '[.relations[]?.id] | .[] | select(. != null)' 2>/dev/null | sort -n)
	scope_ids=$(cat "${dump}" | yq -r '[.relationscopes[]?._id] | .[] | select(. != null)' 2>/dev/null |
		sed -n 's/.*:r#\([0-9]*\)#.*/\1/p' | sort -n -u)
	settings_ids=$(cat "${dump}" | yq -r '[.settings[]?._id] | .[] | select(. != null)' 2>/dev/null |
		sed -n 's/.*:r#\([0-9]*\)#.*/\1/p' | sort -n -u)

	orphans=$(comm -23 <(echo "${scope_ids}") <(echo "${rel_ids}"))
	if [ -n "${orphans}" ]; then
		echo "$(red "orphaned relation scopes for relation ids: ${orphans}")"
		return 1
	fi
	orphans=$(comm -23 <(echo "${settings_ids}") <(echo "${rel_ids}"))
	if [ -n "${orphans}" ]; then
		echo "$(red "orphaned settings for relation ids: ${orphans}")"
		return 1
	fi
	echo "$(green "no orphaned scopes or settings")"
}

# Fails if any applicationOfferConnections documents remain.
assert_no_connections() {
	local dump="$1"
	local count
	count=$(cat "${dump}" | yq -r '[.applicationOfferConnections[]?._id] | .[] | select(. != null)' 2>/dev/null | wc -l)
	if [ "${count}" -ne 0 ]; then
		echo "    FAIL: ${count} applicationOfferConnections remain"
		return 1
	fi
	echo "$(green "no applicationOfferConnections")"
}

# Fails if any remoteApplications relationcount disagrees with the actual
# number of relations referencing it.
assert_counts_match() {
	local dump="$1"
	# For each remote application, count relations whose endpoints reference it.
	local names
	names=$(cat "${dump}" | yq -r '[.remoteApplications[]?.name] | .[] | select(. != null)' 2>/dev/null)
	for name in ${names}; do
		local recorded actual
		recorded=$(cat "${dump}" | yq -r ".remoteApplications[]? | select(.name == \"${name}\") | .relationcount" 2>/dev/null)
		actual=$(cat "${dump}" | yq -r "[.relations[]? | .endpoints[]? | select(.applicationname == \"${name}\")] | length" 2>/dev/null)
		if [ "${recorded}" != "${actual}" ]; then
			echo "$(red "remote app ${name}: relationcount ${recorded} != actual ${actual}")"
			return 1
		fi
	done
	echo "$(green "all relationcounts match actual relations")"
}

# Fails if any relation has an endpoint application that is missing from
# both the applications and remoteApplications collections.
assert_no_dangling_relations() {
	local dump="$1"
	local app_names remote_names rel_endpoint_apps dangling

	app_names=$(cat "${dump}" | yq -r '[.applications[]?.name] | .[] | select(. != null)' 2>/dev/null | sort -u)
	remote_names=$(cat "${dump}" | yq -r '[.remoteApplications[]?.name] | .[] | select(. != null)' 2>/dev/null | sort -u)
	rel_endpoint_apps=$(cat "${dump}" | yq -r '[.relations[]? | .endpoints[]? | .applicationname] | .[] | select(. != null)' 2>/dev/null | sort -u)

	local all_apps
	all_apps=$(printf '%s\n%s\n' "${app_names}" "${remote_names}" | sort -u)
	dangling=$(comm -23 <(echo "${rel_endpoint_apps}") <(echo "${all_apps}"))
	if [ -n "${dangling}" ]; then
		echo "$(red "relations reference missing applications: ${dangling}")"
		return 1
	fi
	echo "$(green "no relations reference missing applications")"
}

# Fails if any unitstates relation-state key references a relation id that
# is not present in the relations collection.
assert_no_stale_relation_state() {
	local dump="$1"
	local rel_ids state_ids stale

	rel_ids=$(cat "${dump}" | yq -r '[.relations[]?.id] | .[] | select(. != null)' 2>/dev/null | sort -u)
	# The relation-state map is keyed by the relation id as a string;
	# collect the keys from every unit state document. The null guard
	# keeps the expression valid for unit state documents that carry no
	# relation-state map at all (a missing map is not stale data).
	state_ids=$(cat "${dump}" | yq -r '[.unitstates[]? | .["relation-state"]? // {} | keys | .[]?] | .[]' 2>/dev/null | sort -u)

	stale=$(comm -23 <(echo "${state_ids}") <(echo "${rel_ids}"))
	if [ -n "${stale}" ]; then
		echo "$(red "unitstates relation-state references missing relations: ${stale}")"
		return 1
	fi
	echo "$(green "no stale unitstates relation-state")"
}

# wait_for_model <model> <timeout-seconds> <assert-fn>...
# polls the model dump through the given assertion functions until they
# all pass.
wait_for_model() {
	local model="$1" timeout="$2"
	shift 2
	local waited=0 attempt=0
	while :; do
		local dump ok out o
		dump=$(mktemp)
		ok=1
		out=""
		if ! dump_db "${model}" "${dump}" >/dev/null 2>&1; then
			ok=0
			out="    FAIL: could not dump model ${model}\n"
		else
			for assert in "$@"; do
				if o=$("${assert}" "${dump}" 2>/dev/null); then
					out+="${o}\n"
				else
					out+="${o}\n"
					ok=0
				fi
			done
		fi
		rm -f "${dump}"
		if [ "${ok}" -eq 1 ]; then
			printf '%b' "${out}"
			return 0
		fi
		if [ "${waited}" -ge "${timeout}" ]; then
			printf '%b' "${out}"
			echo "$(red "integrity invariants still violated after ${timeout}s")"
			return 1
		fi
		attempt=$((attempt + 1))
		echo "[+] (attempt ${attempt}) integrity invariants not yet met; re-polling ${model}"
		sleep "${SHORT_TIMEOUT}"
		waited=$((waited + SHORT_TIMEOUT))
	done
}

# Clean teardown leaves no orphans.
run_cmr_clean_teardown() {
	echo
	echo "=== run_cmr_clean_teardown: normal remove-relation + remove-saas + remove-offer ==="

	file="${TEST_DIR}/test-cmr-clean-teardown.log"
	ensure "model-offer-clean" "${file}"

	echo "Deploy workload and create the offer"
	juju deploy juju-qa-dummy-source --base ubuntu@22.04
	juju offer dummy-source:sink dummy-offer
	wait_for "dummy-source" "$(idle_condition "dummy-source")"

	echo "Deploy consumer and relate"
	juju add-model model-consume-clean
	juju switch model-consume-clean
	juju deploy juju-qa-dummy-sink --base ubuntu@22.04
	wait_for "dummy-sink" "$(idle_condition "dummy-sink")"

	juju consume "${BOOTSTRAPPED_JUJU_CTRL_NAME}:admin/model-offer-clean.dummy-offer"
	juju relate dummy-sink dummy-offer
	wait_for "dummy-offer" '.applications["dummy-sink"] | .relations.source[0]'

	echo "Clean teardown"
	juju remove-relation dummy-sink dummy-offer
	juju remove-saas dummy-offer
	wait_for null '.applications["dummy-sink"] | .relations'
	wait_for null '."application-endpoints"'

	juju switch model-offer-clean
	wait_for null '.offers."dummy-offer"."total-connected-count"'
	juju remove-offer "admin/model-offer-clean.dummy-offer" -y
	wait_for null '.offers'

	echo "Verify DB integrity after clean teardown"
	DUMP=$(mktemp)
	dump_db_checked "model-offer-clean" "${DUMP}" || return 1

	assert_no_orphaned_scope_settings "${DUMP}" || return 1
	assert_no_stale_relation_state "${DUMP}" || return 1
	assert_no_connections "${DUMP}" || return 1
	assert_no_dangling_relations "${DUMP}" || return 1

	rm -f "${DUMP}"

	echo "Clean up"
	destroy_model "model-offer-clean"
	destroy_model "model-consume-clean"
}

# Force remove-relation (consuming side) doesn't corrupt counts.
run_cmr_force_remove_relation() {
	echo
	echo "=== run_cmr_force_remove_relation: --force on consuming side ==="

	file="${TEST_DIR}/test-cmr-force-remove.log"
	ensure "model-offer-force" "${file}"

	echo "Deploy workload and create the offer"
	juju deploy juju-qa-dummy-source --base ubuntu@22.04
	juju offer dummy-source:sink dummy-offer
	wait_for "dummy-source" "$(idle_condition "dummy-source")"

	echo "Deploy consumer and relate"
	juju add-model model-consume-force
	juju switch model-consume-force
	juju deploy juju-qa-dummy-sink --base ubuntu@22.04
	wait_for "dummy-sink" "$(idle_condition "dummy-sink")"

	juju consume "${BOOTSTRAPPED_JUJU_CTRL_NAME}:admin/model-offer-force.dummy-offer"
	juju relate dummy-sink dummy-offer
	wait_for "dummy-offer" '.applications["dummy-sink"] | .relations.source[0]'

	echo "Force-remove the relation on the consuming side"
	juju remove-relation dummy-sink dummy-offer --force
	wait_for null '.applications["dummy-sink"] | .relations' 300
	juju remove-saas dummy-offer
	# Wait for the saas teardown to propagate before inspecting the
	# offering model.
	wait_for null '."application-endpoints"' 300

	echo "Verify DB integrity on the offering model after force removal"
	juju switch model-offer-force
	# Wait for the offer connection count to drain (may need cleanup time).
	# The subshell contains wait_for's exit on timeout so a slow drain
	# cannot fail the test before the cleanups run.
	( wait_for null '.offers."dummy-offer"."total-connected-count"' 180 ) || true

	wait_for_model "model-offer-force" 180 \
		assert_no_negative_counts \
		assert_counts_match \
		assert_no_orphaned_scope_settings \
		assert_no_stale_relation_state \
		assert_no_connections || return 1

	echo "Clean up"
	juju remove-offer "admin/model-offer-force.dummy-offer" --force -y || true
	destroy_model "model-offer-force"
	destroy_model "model-consume-force"
}

# Force remove-relation by id (offering side) doesn't leave dangling relations.
run_cmr_force_remove_relation_offer_side() {
	echo
	echo "=== run_cmr_force_remove_relation_offer_side: --force by id on offering side ==="

	file="${TEST_DIR}/test-cmr-force-offer-side.log"
	ensure "model-offer-relforce" "${file}"

	echo "Deploy workload and create the offer"
	juju deploy juju-qa-dummy-source --base ubuntu@22.04
	juju offer dummy-source:sink dummy-offer
	wait_for "dummy-source" "$(idle_condition "dummy-source")"

	echo "Deploy consumer and relate"
	juju add-model model-consume-relforce
	juju switch model-consume-relforce
	juju deploy juju-qa-dummy-sink --base ubuntu@22.04
	wait_for "dummy-sink" "$(idle_condition "dummy-sink")"

	juju consume "${BOOTSTRAPPED_JUJU_CTRL_NAME}:admin/model-offer-relforce.dummy-offer"
	juju relate dummy-sink dummy-offer
	wait_for "dummy-offer" '.applications["dummy-sink"] | .relations.source[0]'

	echo "Find the relation id on the offering model"
	juju switch model-offer-relforce
	REL_DUMP=$(mktemp)
	dump_db_checked "model-offer-relforce" "${REL_DUMP}" || return 1
	REL_ID=$(cat "${REL_DUMP}" | yq -r '[.relations[]? | select(.key | test("dummy-source")) | .id] | .[0]' 2>/dev/null)
	rm -f "${REL_DUMP}"
	if [ -z "${REL_ID}" ] || [ "${REL_ID}" = "null" ]; then
		echo "$(red "could not find relation id on offering model")"
		destroy_model "model-offer-relforce"
		destroy_model "model-consume-relforce"
		return 1
	fi
	echo "Found relation id: ${REL_ID}"

	echo "Force-remove the relation by id on the offering side"
	juju remove-relation "${REL_ID}" --force
	wait_for_model "model-offer-relforce" 300 \
		assert_no_negative_counts \
		assert_no_orphaned_scope_settings \
		assert_no_stale_relation_state \
		assert_no_dangling_relations || return 1

	echo "Clean up"
	juju switch model-consume-relforce
	juju remove-relation dummy-sink dummy-offer --force 2>/dev/null || true
	juju remove-saas dummy-offer 2>/dev/null || true
	juju switch model-offer-relforce
	juju remove-offer "admin/model-offer-relforce.dummy-offer" --force -y 2>/dev/null || true
	# Forced relation removal can interrupt a running hook. The integrity
	# assertions above have passed, so do not wait for those hooks in cleanup.
	juju destroy-model --force --destroy-storage --no-prompt model-offer-relforce
	juju destroy-model --force --destroy-storage --no-prompt model-consume-relforce
}

# Re-consume doesn't corrupt counts.
run_cmr_consume_remove_reconsume() {
	echo
	echo "=== run_cmr_consume_remove_reconsume: re-consume the same offer ==="

	file="${TEST_DIR}/test-cmr-reconsume.log"
	ensure "model-offer-recon" "${file}"

	echo "Deploy workload and create the offer"
	juju deploy juju-qa-dummy-source --base ubuntu@22.04
	juju offer dummy-source:sink dummy-offer
	wait_for "dummy-source" "$(idle_condition "dummy-source")"

	echo "First consume cycle"
	juju add-model model-consume-recon
	juju switch model-consume-recon
	juju deploy juju-qa-dummy-sink --base ubuntu@22.04
	wait_for "dummy-sink" "$(idle_condition "dummy-sink")"

	juju consume "${BOOTSTRAPPED_JUJU_CTRL_NAME}:admin/model-offer-recon.dummy-offer"
	juju relate dummy-sink dummy-offer
	wait_for "dummy-offer" '.applications["dummy-sink"] | .relations.source[0]'

	echo "Remove relation and saas (first cycle)"
	juju remove-relation dummy-sink dummy-offer
	juju remove-saas dummy-offer
	wait_for null '.applications["dummy-sink"] | .relations'

	echo "Wait for the offering model to drain the connection"
	juju switch model-offer-recon
	( wait_for null '.offers."dummy-offer"."total-connected-count"' 180 ) || true

	echo "Re-consume the same offer"
	juju switch model-consume-recon
	juju consume "${BOOTSTRAPPED_JUJU_CTRL_NAME}:admin/model-offer-recon.dummy-offer"
	juju relate dummy-sink dummy-offer
	wait_for "dummy-offer" '.applications["dummy-sink"] | .relations.source[0]'

	echo "Verify DB integrity on the offering model after re-consume"
	juju switch model-offer-recon
	DUMP=$(mktemp)
	dump_db_checked "model-offer-recon" "${DUMP}" || return 1

	assert_no_negative_counts "${DUMP}" || return 1
	assert_counts_match "${DUMP}" || return 1
	assert_no_orphaned_scope_settings "${DUMP}" || return 1
	assert_no_stale_relation_state "${DUMP}" || return 1
	assert_no_dangling_relations "${DUMP}" || return 1

	rm -f "${DUMP}"

	echo "Clean up"
	juju switch model-consume-recon
	juju remove-relation dummy-sink dummy-offer
	juju remove-saas dummy-offer
	juju switch model-offer-recon
	( wait_for null '.offers."dummy-offer"."total-connected-count"' 180 ) || true
	juju remove-offer "admin/model-offer-recon.dummy-offer" -y
	destroy_model "model-offer-recon"
	destroy_model "model-consume-recon"
}

# Destroying a consuming model doesn't corrupt the offering model.
run_cmr_destroy_consuming_model() {
	echo
	echo "=== run_cmr_destroy_consuming_model: destroy-model with active CMR ==="

	file="${TEST_DIR}/test-cmr-destroy-consume.log"
	ensure "model-offer-destroy" "${file}"

	echo "Deploy workload and create the offer"
	juju deploy juju-qa-dummy-source --base ubuntu@22.04
	juju offer dummy-source:sink dummy-offer
	wait_for "dummy-source" "$(idle_condition "dummy-source")"

	echo "Deploy consumer and relate"
	juju add-model model-consume-destroy
	juju switch model-consume-destroy
	juju deploy juju-qa-dummy-sink --base ubuntu@22.04
	wait_for "dummy-sink" "$(idle_condition "dummy-sink")"

	juju consume "${BOOTSTRAPPED_JUJU_CTRL_NAME}:admin/model-offer-destroy.dummy-offer"
	juju relate dummy-sink dummy-offer
	wait_for "dummy-offer" '.applications["dummy-sink"] | .relations.source[0]'

	echo "Destroy the consuming model (triggers DestroyWithForce on the offering proxy)"
	juju destroy-model model-consume-destroy --destroy-storage --no-prompt

	echo "Wait for the offering model to drain"
	juju switch model-offer-destroy
	( wait_for null '.offers."dummy-offer"."total-connected-count"' 300 ) || true

	echo "Verify DB integrity on the offering model after consuming model destroy"
	DUMP=$(mktemp)
	dump_db_checked "model-offer-destroy" "${DUMP}" || return 1

	assert_no_negative_counts "${DUMP}" || return 1
	assert_counts_match "${DUMP}" || return 1
	assert_no_orphaned_scope_settings "${DUMP}" || return 1
	assert_no_stale_relation_state "${DUMP}" || return 1
	assert_no_connections "${DUMP}" || return 1
	assert_no_dangling_relations "${DUMP}" || return 1

	rm -f "${DUMP}"

	echo "Clean up"
	juju remove-offer "admin/model-offer-destroy.dummy-offer" --force -y 2>/dev/null || true
	destroy_model "model-offer-destroy"
}

# Goal-state degrades gracefully when a saas app is missing.
run_cmr_goal_state_missing_saas() {
	echo
	echo "=== run_cmr_goal_state_missing_saas: goal-state with missing remote app record ==="

	file="${TEST_DIR}/test-cmr-goal-state.log"
	ensure "model-offer-gs" "${file}"

	echo "Deploy workload and create the offer"
	juju deploy juju-qa-dummy-source --base ubuntu@22.04
	juju offer dummy-source:sink dummy-offer
	wait_for "dummy-source" "$(idle_condition "dummy-source")"

	echo "Deploy consumer and relate"
	juju add-model model-consume-gs
	juju switch model-consume-gs
	juju deploy juju-qa-dummy-sink --base ubuntu@22.04
	wait_for "dummy-sink" "$(idle_condition "dummy-sink")"

	juju consume "${BOOTSTRAPPED_JUJU_CTRL_NAME}:admin/model-offer-gs.dummy-offer"
	juju relate dummy-sink dummy-offer
	wait_for "dummy-offer" '.applications["dummy-sink"] | .relations.source[0]'

	echo "Force-destroy the saas (leaves the relation Dying, remote app doc gone)"
	juju remove-saas dummy-offer --force

	# Run goal-state on the consuming unit. The facade
	# skips the missing endpoint and returns valid goal state.
	echo "Run goal-state on the consuming unit"
	if GS_OUTPUT=$(juju exec --unit dummy-sink/0 'goal-state --format=json' 2>&1); then
		GS_RC=0
	else
		GS_RC=$?
	fi

	if [ ${GS_RC} -ne 0 ]; then
		# Check whether the failure is the expected goal-state error.
		if echo "${GS_OUTPUT}" | grep -q "saas application.*not found"; then
			echo "$(red "goal-state failed with 'saas application not found'")"
			# Clean up before returning failure.
			juju remove-relation dummy-sink dummy-offer --force 2>/dev/null || true
			juju switch model-offer-gs
			juju remove-offer "admin/model-offer-gs.dummy-offer" --force -y 2>/dev/null || true
			juju destroy-model --force --destroy-storage --no-prompt model-consume-gs
			juju destroy-model --force --destroy-storage --no-prompt model-offer-gs
			return 1
		fi

		echo "$(red "goal-state failed with unexpected error: ${GS_OUTPUT}")"
		juju remove-relation dummy-sink dummy-offer --force 2>/dev/null || true
		juju switch model-offer-gs
		juju remove-offer "admin/model-offer-gs.dummy-offer" --force -y 2>/dev/null || true
		juju destroy-model --force --destroy-storage --no-prompt model-consume-gs
		juju destroy-model --force --destroy-storage --no-prompt model-offer-gs
		return 1
	fi

	echo "$(green "goal-state succeeded despite missing saas application")"

	echo "Clean up"
	juju remove-relation dummy-sink dummy-offer --force 2>/dev/null || true
	juju switch model-offer-gs
	# The connection drain is not expected to complete here: the saas
	# was force-destroyed and the offering unit is left blocked. Poll
	# briefly for diagnostics in a subshell so a timeout cannot kill the
	# test, then force-remove everything.
	( wait_for null '.offers."dummy-offer"."total-connected-count"' 60 ) || true
	juju remove-offer "admin/model-offer-gs.dummy-offer" --force -y 2>/dev/null || true
	# Forced SAAS removal can interrupt a relation hook. The goal-state
	# assertion is complete, so force-destroy the fixtures without waiting
	# for those hooks to recover.
	juju destroy-model --force --destroy-storage --no-prompt model-consume-gs
	juju destroy-model --force --destroy-storage --no-prompt model-offer-gs
}

test_cmr_integrity() {
	if [ "$(skip 'test_cmr_integrity')" ]; then
		echo "==> TEST SKIPPED: CMR integrity tests"
		return
	fi

	set_verbosity

	echo "==> Checking for dependencies"
	check_dependencies juju go

	file="${TEST_DIR}/test-cmr-integrity.log"

	bootstrap "test-cmr-integrity" "${file}"

	(
		cd .. || exit

		run "run_cmr_clean_teardown"
		run "run_cmr_force_remove_relation"
		run "run_cmr_force_remove_relation_offer_side"
		run "run_cmr_consume_remove_reconsume"
		run "run_cmr_destroy_consuming_model"
		run "run_cmr_goal_state_missing_saas"
	)

	destroy_controller "test-cmr-integrity"
}
